      {status === "loading" && <p>검색 중...</p>}
      {status === "error" && <p role="alert">상품을 불러오지 못했습니다.</p>}

      <ul>
        {products.map((product) => (
          <li key={product}>{product}</li>
        ))}
      </ul>
    </section>
  );
}

