def parse_config(env: dict[str, str]) -> dict[str, int | bool]:
    result: dict[str, int | bool] = {}
    errors: list[tuple[str, str]] = []

    def is_decimal_integer(text: str) -> bool:
        if text.startswith(("+", "-")):
            text = text[1:]
        return bool(text) and all("0" <= char <= "9" for char in text)

    def parse_integer(name: str, default: str, minimum: int, maximum: int) -> None:
        text = env[name].strip() if name in env else default

        if not is_decimal_integer(text):
            errors.append((name, f"{name}: 값 {text!r}은(는) 10진 정수가 아닙니다"))
            return

        value = int(text, 10)
        if not minimum <= value <= maximum:
            errors.append(
                (name, f"{name}: 값 {text!r}은(는) {minimum} 이상 {maximum} 이하여야 합니다")
            )
            return

        result[name] = value

    parse_integer("PORT", "8080", 1, 65535)
    parse_integer("WORKERS", "4", 1, 32)

    debug_text = env["DEBUG"].strip() if "DEBUG" in env else "false"
    normalized_debug = debug_text.lower()
    if normalized_debug == "true":
        result["DEBUG"] = True
    elif normalized_debug == "false":
        result["DEBUG"] = False
    else:
        errors.append(
            ("DEBUG", f"DEBUG: 값 {debug_text!r}은(는) true 또는 false여야 합니다")
        )

    if errors:
        errors.sort(key=lambda item: item[0])
        raise ValueError("; ".join(message for _, message in errors))

    return result

