import re


_INT_PATTERN = re.compile(r"[+-]?[0-9]+")


def parse_config(env: dict[str, str]) -> dict:
    errors: dict[str, str] = {}
    result: dict[str, int | bool] = {}

    integer_fields = (
        ("PORT", "8080", 1, 65535, "PORT: 1~65535 범위의 10진 정수여야 합니다"),
        ("WORKERS", "4", 1, 32, "WORKERS: 1~32 범위의 10진 정수여야 합니다"),
    )

    for name, default, minimum, maximum, error_message in integer_fields:
        text = env.get(name, default).strip()

        if _INT_PATTERN.fullmatch(text) is None:
            errors[name] = error_message
            continue

        value = int(text, 10)
        if not minimum <= value <= maximum:
            errors[name] = error_message
        else:
            result[name] = value

    debug_text = env.get("DEBUG", "false").strip()
    if debug_text == "true":
        result["DEBUG"] = True
    elif debug_text == "false":
        result["DEBUG"] = False
    else:
        errors["DEBUG"] = "DEBUG: 'true' 또는 'false'여야 합니다"

    if errors:
        message = "; ".join(errors[name] for name in sorted(errors))
        raise ValueError(message)

    return {
        "PORT": result["PORT"],
        "WORKERS": result["WORKERS"],
        "DEBUG": result["DEBUG"],
    }

class LengthPrefixedParser:
    MAX_PAYLOAD_SIZE = 1024

    def __init__(self) -> None:
        self._buffer = bytearray()
        self._expected_length: int | None = None
        self._failed = False

    def feed(self, data: bytes) -> list[bytes]:
        if not isinstance(data, bytes):
            raise TypeError("data must be bytes")
        if self._failed:
            raise ValueError("parser is locked after an invalid frame length")

        self._buffer.extend(data)
        frames: list[bytes] = []

        while True:
            if self._expected_length is None:
                if len(self._buffer) < 4:
                    break

                length = int.from_bytes(self._buffer[:4], "big")
                del self._buffer[:4]

                if length > self.MAX_PAYLOAD_SIZE:
                    self._failed = True
                    self._buffer.clear()
                    raise ValueError("payload length exceeds 1024 bytes")

                self._expected_length = length

            if len(self._buffer) < self._expected_length:
                break

            payload = bytes(self._buffer[:self._expected_length])
            del self._buffer[:self._expected_length]
            frames.append(payload)
            self._expected_length = None

        return frames

    def reset(self) -> None:
        self._buffer.clear()
        self._expected_length = None
        self._failed = False

class FrameParser:
    MAX_PAYLOAD_SIZE = 1024
    HEADER_SIZE = 4

    def __init__(self) -> None:
        self._buffer = bytearray()
        self._failed = False

    def feed(self, data: bytes) -> list[bytes]:
        if self._failed:
            raise RuntimeError("파서가 고장 상태입니다. reset() 후 다시 사용하세요.")
        if not isinstance(data, bytes):
            raise TypeError("data는 bytes여야 합니다.")

        self._buffer.extend(data)
        frames: list[bytes] = []

        while True:
            if len(self._buffer) < self.HEADER_SIZE:
                break

            payload_size = int.from_bytes(
                self._buffer[:self.HEADER_SIZE],
                byteorder="big",
                signed=False,
            )

            if payload_size > self.MAX_PAYLOAD_SIZE:
                self._failed = True
                raise ValueError(
                    f"페이로드 길이 {payload_size}는 최대 허용 길이 "
                    f"{self.MAX_PAYLOAD_SIZE}를 초과합니다."
                )

            frame_size = self.HEADER_SIZE + payload_size
            if len(self._buffer) < frame_size:
                break

            payload = bytes(self._buffer[self.HEADER_SIZE:frame_size])
            del self._buffer[:frame_size]
            frames.append(payload)

        return frames

    def reset(self) -> None:
        self._buffer.clear()
        self._failed = False
